// Incremental refresh filter on the fact query (RangeStart and RangeEnd are DateTime parameters)
Filtered = Table.SelectRows(
    Sales,
    each [OrderDateTime] >= RangeStart and [OrderDateTime] < RangeEnd
)

exercises.answer:
EVALUATE
VAR Sales =
    DATATABLE (
        "Product", STRING, "Qty", INTEGER, "Price", DOUBLE,
        {
            { "Laptop", 3, 900 },
            { "Mouse", 40, 15 },
            { "Screen", 5, 180 },
            { "Desk", 2, 250 }
        }
    )
RETURN
    ROW ( "Total revenue", SUMX ( Sales, [Qty] * [Price] ) )

EVALUATE
VAR Sales =
    DATATABLE (
        "Category", STRING, "Product", STRING, "Qty", INTEGER, "Price", DOUBLE,
        {
            { "IT", "Laptop", 3, 900 },
            { "IT", "Mouse", 40, 15 },
            { "Office", "Desk", 2, 250 },
            { "Office", "Chair", 6, 120 }
        }
    )
RETURN
    GROUPBY ( Sales, [Category], "Revenue", SUMX ( CURRENTGROUP (), [Qty] * [Price] ) )
